import sqlite3

def handle(query, state):
    flag = state.get("flag", "")
    user_id = (query.get("user_id") or [""])[0]

    conn = sqlite3.connect(":memory:")
    cur = conn.cursor()

    cur.execute(
        "CREATE TABLE accounts (id INTEGER PRIMARY KEY, user_id TEXT, email TEXT, balance REAL)"
    )
    cur.execute(
        "CREATE TABLE admin_flags (id INTEGER PRIMARY KEY, flag_value TEXT)"
    )
    cur.executemany(
        "INSERT INTO accounts (user_id, email, balance) VALUES (?, ?, ?)",
        [("u001", "alice@example.com", 500.0), ("u002", "bob@example.com", 250.0), ("u003", "charlie@example.com", 1000.0)],
    )
    cur.execute(
        "INSERT INTO admin_flags (flag_value) VALUES (?)",
        (flag,),
    )
    conn.commit()

    sql = "SELECT user_id, email, balance FROM accounts WHERE user_id = '" + user_id + "'"
    try:
        cur.execute(sql)
        rows = cur.fetchall()
    except sqlite3.Error as e:
        conn.close()
        return 500, {"Content-Type": "text/plain"}, "Error: " + str(e)

    conn.close()

    if not rows:
        return 200, {"Content-Type": "text/plain"}, "Account not found."

    lines = []
    for row in rows:
        lines.append("|".join(str(c) for c in row))
    return 200, {"Content-Type": "text/plain"}, "\n".join(lines)
